#!/bin/bash
# Task 183-w24-sweepfull -- meshsim sim/ WORKER24 (branch sim-w24; P6, inventory D10).
# Sweep's full mode, v1.35 against v1.3: v1.3's `java Sweep full` run in sim/ref through oracle/ref/sortlogs.sh
# (step sweep-full: a scratch copy of ref/meshsim with the committed images), and the C++ `sweep full` (tests/
# sweep_main.cpp, built here with clang, MODE=suite), side by side. Compared byte for byte: the log (stdout and stderr
# together, as run_tests.sh records a step) and results/sweep-full.csv. Both returned; v1.3's become the fixtures.
# Not timing (wall times recorded only); the machine recorded (D21). From an embedded kit. Writes only
# results/183-w24-sweepfull/. Scratch in /tmp, removed first and at the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/183-w24-sweepfull; mkdir -p "$RES"
W=/tmp/w24-183; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "25a99adc8b21cfcde875c8d01d2fb12ef5fa49049140307e754ba2eeed18af36" ] || { echo "kit sha256 mismatch (want 25a99adc8b21cfcde875c8d01d2fb12ef5fa49049140307e754ba2eeed18af36)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
S=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
{ echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs"; lscpu | grep -E '^(Model name|Thread|Core|Socket|CPU max MHz)'
  grep MemTotal /proc/meminfo; java -version 2>&1 | head -1; clang++ --version | head -1; } | tee "$RES/machine.txt"
(cd "$S" && make -s -j4 CC_NAME=clang MODE=suite build/clang-suite/sweep > "$RES/build.out" 2>&1) || { cat "$RES/build.out"; verdict build FAIL; echo FAILED; exit 1; }
# the C++ sweep (its CSV into the scratch tree's results/) and v1.3's, side by side
( cd "$S" && s=$(date +%s); ./build/clang-suite/sweep full > "$RES/cpp-sweep-full.log" 2>&1; rc=$?; echo "C++ sweep full: exit $rc, $(( $(date +%s) - s )) s" > "$RES/cpp.time"; exit $rc ) & cp=$!
( cd "$S" && s=$(date +%s); JS=-Xmx8g bash oracle/ref/sortlogs.sh --fixtures sweep-full > "$RES/sortlogs.out" 2>&1; rc=$?; echo "v1.3 Sweep full: exit $rc, $(( $(date +%s) - s )) s" > "$RES/ref.time"; exit $rc ) & rp=$!
wait $cp && verdict cpp-run PASS || verdict cpp-run FAIL
wait $rp && verdict ref-run PASS || verdict ref-run FAIL
cat "$RES/cpp.time" "$RES/ref.time"
cp "$S/results/sweep-full.csv" "$RES/cpp-sweep-full.csv" 2>/dev/null
cp "$S/tests/sort/ref/sweep-full.log" "$RES/ref-sweep-full.log" 2>/dev/null; cp "$S/tests/sort/ref/sweep-full.csv" "$RES/ref-sweep-full.csv" 2>/dev/null
cmp "$RES/cpp-sweep-full.log" "$RES/ref-sweep-full.log" && verdict log-equal PASS || { diff "$RES/cpp-sweep-full.log" "$RES/ref-sweep-full.log" | head -20; verdict log-equal FAIL; }
cmp "$RES/cpp-sweep-full.csv" "$RES/ref-sweep-full.csv" && verdict csv-equal PASS || { diff "$RES/cpp-sweep-full.csv" "$RES/ref-sweep-full.csv" | head -20; verdict csv-equal FAIL; }
tail -8 "$RES/ref-sweep-full.log"
(cd "$RES" && sha256sum $(find . -type f ! -name SHA256SUMS ! -name run.log | sort) > SHA256SUMS)
echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
